md<-load_meta();pa<-fread(out('03_marker_review/shortlist_diagnostic_sample_contrasts.tsv.gz'));cl<-fread(out('03_marker_review/shortlist_diagnostic_cluster_summary.tsv'));sig<-fread(out('03_marker_review/signature_membership.tsv'))
chosen<-data.table(state=c(rep('C8',3),rep('C12',3),rep('C16',3)),resolution=c(rep('r04',3),rep('r06',6)),gene_id=c('EGR1','GADD45B','ELOVL5','HIPK3','GSE1','ELOVL5','NRARP','IDI1','LDLR'),role=c('Best of these C8 discrimination candidates; inducible transcription signal','Supportive response gene; C13 expression higher','Lipid-support gene with local C6/C3 support; broader program, not C8-specific','C12 versus C16 expression discriminator; weaker versus rest','C12 versus C16 discriminator; modest detection; C14/C15 may be higher','C12 lipid-support gene; not a C12/C16 discriminator','C16 versus rest candidate; C12 nearly equal; limited subtype specificity','C16 sterol-support gene; MP10 input gene; not C16-specific','C16 lipid-uptake support; MP10 input gene; not C16-specific'))
