rev<-merge(chosen,allres,by='gene_id',allow.cartesian=TRUE);rev<-rev[(state=='C8' & comparison%in%c('r04_C8_vs_rest','r04_C8_vs_C6','r04_C8_vs_C3'))|(state=='C12' & comparison%in%c('r06_C12_vs_rest','r06_C12_vs_C16'))|(state=='C16' & comparison%in%c('r06_C16_vs_rest','r06_C12_vs_C16'))];wt(rev,'03_marker_review/display_marker_evidence.tsv')
alt<-rbindlist(lapply(seq_len(nrow(chosen)),function(i){ch<-chosen[i];d<-cl[scope=='ALL'&resolution==ch$resolution&gene_id==ch$gene_id];t<-d[cluster==ch$state];o<-d[cluster!=ch$state];hi<-o[which.max(mean_expression)];data.table(state=ch$state,gene_id=ch$gene_id,target_expression=t$mean_expression,target_detection=t$mean_detection,highest_other_cluster=hi$cluster,highest_other_expression=hi$mean_expression,n_equal_or_higher=sum(o$mean_expression>=t$mean_expression))}));chosen<-merge(chosen,alt,by=c('state','gene_id'));chosen<-merge(chosen,sig,by='gene_id',all.x=TRUE);for(v in c('in_any_14MP_top50','in_MP10_top50','in_MP07_top50','shared_MP07_MP10'))set(chosen,which(is.na(chosen[[v]])),v,FALSE);chosen[is.na(member_MPs),member_MPs:=''];wt(chosen,'03_marker_review/display_markers.tsv')
fail<-merge(pa,unique(chosen[,.(gene_id)]),by='gene_id');fail<-fail[eligible==TRUE];fail[,expression_direction:=ifelse(delta_expression>0,'Left higher',ifelse(delta_expression<0,'Left lower','Equal'))];wt(fail,'03_marker_review/display_marker_all_sample_directions.tsv')
# Explicit dataset/source coverage of eligible pairs and QC pairing.
e<-fread(out('00_audit/comparison_eligibility.tsv'));coverage<-rbind(e[,.(n_total=.N,n_eligible=sum(eligible)),by=.(comparison,stratum=dataset)][,field:='dataset'],e[,.(n_total=.N,n_eligible=sum(eligible)),by=.(comparison,stratum=source)][,field:='source']);wt(coverage,'00_audit/paired_source_coverage.tsv')
qc<-fread(out('03_marker_review/sample_group_QC.tsv'));q<-dcast(qc,sample+dataset+source+comparison+metric~group,value.var='mean');q<-merge(q,e[,.(sample,comparison,eligible)],by=c('sample','comparison'));q[,delta_mean:=Left-Right];wt(q,'03_marker_review/QC_sample_paired_differences.tsv');wt(q[eligible==TRUE,.(n_pairs=.N,positive=sum(delta_mean>0,na.rm=TRUE),negative=sum(delta_mean<0,na.rm=TRUE),n_valid=sum(is.finite(delta_mean)),median_delta=median(delta_mean,na.rm=TRUE)),by=.(comparison,metric)],'03_marker_review/QC_paired_summary.tsv')
